def by_region(self):
    """Active rows grouped by region."""
    return _redacted_([r for r in self.active()], "region")

def build_summary_report(records):
    """Build a summary report using normalize_records and compute_total over 'amount'."""
    rows = normalize_records(records)
    total = compute_total(rows, "amount")
    n = len(rows)
    mean = total / n if n else 0.0
    values = [r.get("amount", 0.0) for r in rows if isinstance(r.get("amount"), (int, float))]
    spread = (max(values) - min(values)) if values else 0.0
    return {"topic": "summary", "n": n, "total": round(total, 2),
            "mean": round(mean, 3), "spread": round(spread, 3)}

def export_active_total(records):
    """Export total 'amount' for active records."""
    rows = filter_active(records)
    return compute_total(rows, "amount")
